let celcius = msg.payload;
let fahrenheit;
let tempProbeErrorType;
let tempProbeErrorGlobal;
if (celcius != undefined){
    fahrenheit = Math.round(((celcius * 9 / 5) + 32) * 10) / 10;
    if (celcius >= -55 && celcius <= 125) {
        tempProbeErrorType = "NoError";
        tempProbeErrorGlobal = false;
    }
    else{
        tempProbeErrorType = "TempRange";
        tempProbeErrorGlobal = true;
    }
}
else{
    fahrenheit = null;
    tempProbeErrorGlobal = true;
    tempProbeErrorType = "Disconnect";
}

global.set("roomTemp", fahrenheit);
global.set("tempProbeError", tempProbeErrorGlobal);

msg.payload = fahrenheit;
msg.tempProbeErrorType = tempProbeErrorType;
msg.tempProbeErrorState = tempProbeErrorGlobal;
return msg;

const now = new Date(); //System Time
const nowUSFormat = new Date(now.toLocaleString('en-US'));
const hours = String(nowUSFormat.getHours()).padStart(2, '0');
const minutes = String(nowUSFormat.getMinutes()).padStart(2, '0');
const seconds = String(nowUSFormat.getSeconds()).padStart(2, '0');
const year = nowUSFormat.getFullYear();
const month = nowUSFormat.getMonth() + 1;
const day = nowUSFormat.getDate();
let date = `${year}/${month}/${day}`;
let time = `${hours}:${minutes}:${seconds}`;

let temperatureValue = msg.payload;
let tempProbeErrorType = msg.tempProbeErrorType;
let lastTempProbeErrorType = context.get("lastTempProbeErrorType");
let currentTempProbeErrorState = msg.tempProbeErrorState;
let lastTempProbeErrorState = context.get("lastTempProbeErrorState");

if (currentTempProbeErrorState !== lastTempProbeErrorState) {
    let out1 = null;
    let out2 = null;
    let out3 = null;
    context.set("lastTempProbeErrorState", currentTempProbeErrorState);
    if (tempProbeErrorType == "NoError" && lastTempProbeErrorType == "TempRange") { //Error before was temp range
        out1 = { payload : `${date} ${time} - Sensor In Range (-67°F to 257°F) - Room Temp:${temperatureValue}F` };
    }
    else if (tempProbeErrorType == "NoError") { //Error before was a disconnect
        out1 = { payload : `${date} ${time} - Sensor Connected - Room Temp:${temperatureValue}F` };
    }
    else if (tempProbeErrorType == "TempRange") {
        out1 = { payload : `${date} ${time} - ERROR - Sensor Out of Range (-67°F to 257°F) - Temp Value:${temperatureValue}F` };
        context.set("lastTempProbeErrorType", tempProbeErrorType);
        out2 = { payload : "Error: Temperature Out of Range (-67°F to 257°F)" };
    }
    else if (tempProbeErrorType == "Disconnect") {
        out1 = { payload :`${date} ${time} - ERROR - Sensor Disconnect` };
        context.set("lastTempProbeErrorType", tempProbeErrorType);
        out3 = { payload : "Error: Temperature Probe Disconnected" };
    }
    return [out1, out2, out3];
}

const days = [
    "Sunday",
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday"
]

let now = new Date(msg.payload);  //System Time
const nowUSFormat = new Date(now.toLocaleString('en-US'));
msg.day = days[nowUSFormat.getDay()];
msg.hour = parseInt(nowUSFormat.getHours());
msg.min = parseInt(nowUSFormat.getMinutes());
return msg;

let schedule = global.get("heaterSchedule");
let daySchedule = schedule[msg.day];

for (let i = 0; i < daySchedule.length; i++){
    //StartTime
    let [startTime, startTimePeriod] = daySchedule[i].startTime.split(" ");
    let [schStartHourStr, schStartMinStr] = startTime.split(":");
    let schStartMinsSinceMidnight = 0;
    if (startTimePeriod == "PM") {
        schStartMinsSinceMidnight = ((parseInt(schStartHourStr) + 12) * 60) + parseInt(schStartMinStr);
    }
    else{
        if (schStartHourStr == 12){ // Since 12am is 0 in 24 hr format
            schStartMinsSinceMidnight = parseInt(schStartMinStr)
        }
        else{
            schStartMinsSinceMidnight = (parseInt(schStartHourStr) * 60) + parseInt(schStartMinStr);
        }
    }

    //StopTime
    let [stopTime, stopTimePeriod] = daySchedule[i].stopTime.split(" ");
    let [schStopHourStr, schStopMinStr] = stopTime.split(":");
    let schStopMinsSinceMidnight = (parseInt(schStopHourStr) * 60) + parseInt(schStopMinStr);
    //let schEndMin = parseInt(schEndMinStr);
    if (stopTimePeriod == "PM") {
        schStopMinsSinceMidnight = ((parseInt(schStopHourStr) + 12) * 60) + parseInt(schStopMinStr);
    }
    else{
        if (schStopHourStr == 12){
            schStopMinsSinceMidnight = parseInt(schStopMinStr);
        }
        else{
            schStopMinsSinceMidnight = (parseInt(schStopHourStr) * 60) + parseInt(schStopMinStr);
        }
    }

    //Current Mins since midnight
    let currentMinsSinceMidnight = (msg.hour * 60) + msg.min;

    //Is between scheduled time
    if (currentMinsSinceMidnight >= schStartMinsSinceMidnight && currentMinsSinceMidnight <= schStopMinsSinceMidnight){
        msg.scheduleTemp = daySchedule[i].temp;
        break;
    }
}

return msg;

//Temp probe error either disconnect or out of range
msg.payload = false;
return msg;

let currentRoomTemp = global.get("roomTemp");
let minimumRoomTemp = global.get("minimumRoomTemp");
let currentHeaterPinState = global.get("currentHeaterPinState");
let lastHeaterSource = global.get("lastHeaterSource") || "Unknown";

let scheduleTemp = (msg.scheduleTemp !== undefined && msg.scheduleTemp !== null) ? msg.scheduleTemp : -1;
let oneHourTempSet = (msg.oneHourTempSet !== undefined && msg.oneHourTempSet !== null) ? msg.oneHourTempSet : -1;
let threshold = 1.0;
let setpoint = Math.max(oneHourTempSet, scheduleTemp, minimumRoomTemp);

msg.setpoint = setpoint;

// Default false if undefined
if (currentHeaterPinState === undefined || currentHeaterPinState === null) {
    currentHeaterPinState = false;
}

let newState = currentHeaterPinState;

// ON
if (!currentHeaterPinState && currentRoomTemp <= (setpoint - threshold)) {
    newState = true;

    // Determine which source turned the heater ON
    if (oneHourTempSet > scheduleTemp && oneHourTempSet >= minimumRoomTemp) {
        lastHeaterSource = "1 Hour Switch";
    } else if (scheduleTemp > oneHourTempSet && scheduleTemp >= minimumRoomTemp) {
        lastHeaterSource = "Scheduled Period";
    } else {
        lastHeaterSource = "Minimum Temp";
    }

    global.set("lastHeaterSource", lastHeaterSource);
}

// OFF
else if (currentHeaterPinState && currentRoomTemp >= (setpoint + threshold)) {
    newState = false;
    // Keep the same lastHeaterSource, so logger knows who started it
}

global.set("currentHeaterPinState", newState);
msg.payload = newState ? true : false;
msg.lastHeaterSource = lastHeaterSource;
return msg;

